#ifndef MATERIAL_TARGET_ANALYTIC_H
#define MATERIAL_TARGET_ANALYTIC_H
#include "material_target_domain.h"
/* A priori holomorphic majorants for the preserved P3+v0 function.
 * One fixed Cauchy radius3/4 and Gauss16. No rule-difference remainder,
 * precision search, empirical error multiplier or physical-state change. */
namespace material_target_analytic {
namespace ti=material_target_inverse;namespace tg=material_target_general;namespace td=material_target_domain;namespace mf=material_forward;
using Q=ti::Q;using S=ti::S;using P=ti::P;
static Q product(Q a,Q b){return ti::mul(a,b);}static Q sum(Q a,Q b){return ti::add(a,b);}
static Q difference_down(Q a,Q b){return mf::FP<Q>::down(a-b);}
static Q quotient_up(Q a,Q b){need(b>0,"positive analytic majorant denominator");return mf::FP<Q>::up(a/b);}
static Q poly_norm(const P&p,const Q*r){Q out=0;for(int i=0;i<=p.degree;i++)for(int j=0;i+j<=p.degree;j++)out=sum(out,product(ti::mag(p.c[i][j]),product(ti::ipow(r[0],i),ti::ipow(r[1],j))));return out;}
static S exp_bound(S x){Q n=expq(x.n),lo=expq(ti::lower(x)),hi=expq(ti::upper(x));lo=mf::FP<Q>::down(lo-mf::libm_error(lo));hi=mf::FP<Q>::up(hi+mf::libm_error(hi));return {n,mf::FP<Q>::up(std::max(fabsq(n-lo),fabsq(hi-n)))};}
struct Bounds {bool pass=false;const char*reason="";Q H[2][2][2]={},F[4]={},V[4]={},v[2]={},x[2]={},Jlo=0,Jhi=0,rho=0,moment[12]={};};
static Bounds bounds(const tg::Map&m,const curved::Packet&p,const Q*r,const Q*physical_center=nullptr,const Q*physical_radius=nullptr){
    Bounds b;Q coord[2]={sum(fabsq(m.anchor[0]),r[0]),sum(fabsq(m.anchor[1]),r[1])},variation=0;S radial=S(m.anchor[0])*S(m.anchor[0])+S(m.anchor[1])*S(m.anchor[1]);for(int k=0;k<2;k++)variation=sum(variation,sum(product(product(Q(2),fabsq(m.anchor[k])),r[k]),product(r[k],r[k])));S z=radial+S(Q(m.eps))*S(Q(m.eps));Q zlo=difference_down(ti::lower(z),variation);if(zlo<=0){b.reason="initial_v0_complex_branch";return b;}Q omega=ti::mag(mf::power(S(zlo),Q(-.75L))),od[2],odd[2][2];for(int i=0;i<2;i++){od[i]=quotient_up(product(product(Q(1.5L),coord[i]),omega),zlo);for(int j=0;j<2;j++)odd[i][j]=sum(i==j?quotient_up(product(Q(1.5L),omega),zlo):Q(0),quotient_up(product(product(product(Q(5.25L),coord[i]),coord[j]),omega),product(zlo,zlo)));}int E[2][2]={{0,-1},{1,0}};Q rot[2]={coord[1],coord[0]};
    for(int k=0;k<2;k++)for(int i=0;i<2;i++)for(int j=0;j<2;j++){b.H[k][i][j]=poly_norm(ti::derivative(ti::derivative(m.x[k],i),j),r);for(int a=0;a<2;a++){Q h=sum(product(rot[a],odd[i][j]),sum(E[a][i]?od[j]:Q(0),E[a][j]?od[i]:Q(0)));b.H[k][i][j]=sum(b.H[k][i][j],product(ti::mag(m.Bx[k][a]),h));}}
    auto center=tg::evaluate<Q>(m,S(m.anchor[0]),S(m.anchor[1]));Q dF[4]={};for(int k=0;k<2;k++)for(int i=0;i<2;i++){for(int j=0;j<2;j++)dF[2*k+i]=sum(dF[2*k+i],product(b.H[k][i][j],r[j]));b.F[2*k+i]=sum(ti::mag(center.F[2*k+i]),dF[2*k+i]);b.V[2*k+i]=poly_norm(ti::derivative(m.v[k],i),r);for(int a=0;a<2;a++){Q dv=sum(product(rot[a],od[i]),E[a][i]?omega:Q(0));b.V[2*k+i]=sum(b.V[2*k+i],product(ti::mag(m.Bv[k][a]),dv));}}
    Q dJ=0;for(auto pair:{std::pair<int,int>{0,3},{1,2}}){int i=pair.first,j=pair.second;dJ=sum(dJ,sum(product(ti::mag(center.F[i]),dF[j]),sum(product(ti::mag(center.F[j]),dF[i]),product(dF[i],dF[j]))));}b.Jlo=difference_down(ti::lower(center.J),dJ);b.Jhi=sum(ti::mag(center.J),dJ);if(b.Jlo<=0){b.reason="complex_map_J_branch";return b;}
    for(int i=0;i<2;i++){b.v[i]=ti::mag(center.velocity[i]);for(int j=0;j<2;j++)b.v[i]=sum(b.v[i],product(b.V[2*i+j],r[j]));}
    // Principal sqrt(r^2) has positive real part throughout this box.
    Q r2lo=difference_down(ti::lower(radial),variation);if(r2lo<=0){b.reason="reference_density_complex_radius_branch";return b;}Q radial_min=ti::lower(mf::root(S(r2lo))),radial_max=ti::mag(mf::root(S(sum(ti::mag(radial),variation))));S inner=exp_bound(S(2)*(S(radial_max)-S(Q(p.parameters[4])))/S(Q(p.parameters[8]))),outer=exp_bound(S(-2)*(S(Q(p.parameters[5]))-S(radial_max))/S(Q(p.parameters[8])));Q ie=ti::mag(inner),oe=ti::mag(outer);if(ie>=1||oe>=1){b.reason="density_logistic_pole_exclusion";return b;}Q gate=product(quotient_up(ie,difference_down(1,ie)),quotient_up(1,difference_down(1,oe)));b.rho=sum(Q(p.parameters[6]),product(quotient_up(Q(p.parameters[9]),ti::lower(S(radial_min)+S(Q(p.parameters[7])))),gate));
    Q xc[2],xr[2];for(int i=0;i<2;i++){xc[i]=physical_center?physical_center[i]:center.position[i].n;xr[i]=physical_radius?physical_radius[i]:center.position[i].e;if(!physical_radius)for(int j=0;j<2;j++)xr[i]=sum(xr[i],product(b.F[2*i+j],r[j]));b.x[i]=sum(fabsq(xc[i]),xr[i]);}S potential=S(xc[0])*S(xc[0])+S(xc[1])*S(xc[1])+S(Q(p.parameters[3]))*S(Q(p.parameters[3]));Q pv=0;for(int i=0;i<2;i++)pv=sum(pv,sum(product(product(Q(2),fabsq(xc[i])),xr[i]),product(xr[i],xr[i])));Q potential_lo=difference_down(ti::lower(potential),pv);if(potential_lo<=0){b.reason="physical_potential_complex_branch";return b;}
    Q density=quotient_up(b.rho,b.Jlo),v2=sum(product(b.v[0],b.v[0]),product(b.v[1],b.v[1])),x2=sum(product(b.x[0],b.x[0]),product(b.x[1],b.x[1])),Pmax=ti::mag(S(Q(p.parameters[2]))*mf::power(S(b.Jlo),Q(-p.parameters[1])));Q div=quotient_up(sum(sum(product(b.V[0],b.F[3]),product(b.V[1],b.F[2])),sum(product(b.V[2],b.F[1]),product(b.V[3],b.F[0]))),b.Jlo);
    b.moment[MASS]=density;b.moment[PX]=product(density,b.v[0]);b.moment[PY]=product(density,b.v[1]);b.moment[ANGULAR]=product(density,sum(product(b.x[0],b.v[1]),product(b.x[1],b.v[0])));b.moment[KINETIC]=product(Q(.5L),product(density,v2));b.moment[THERMAL]=quotient_up(Pmax,ti::lower(S(Q(p.parameters[1]))-S(1)));b.moment[VOLUME]=1;b.moment[QX]=product(density,b.x[0]);b.moment[QY]=product(density,b.x[1]);b.moment[POLAR]=product(density,x2);b.moment[THERMAL_RATE]=product(Pmax,div);b.moment[POTENTIAL]=product(density,ti::mag(S(1)/mf::root(S(potential_lo))));b.pass=true;b.reason="pass";return b;
}
struct Sector {bool pass=false;const char*reason="";Q ref_radius[2]={},physical_radius[2]={},contraction=0,invariance_ratio=0,Jfan=0,remainder[12]={};Bounds field;};
static Sector sector(const curved::Packet&p,const curved::Record&r,const tg::Map&m,const td::Domain&domain,const td::Loop&loop,const td::Boundary&boundary,int index){
    Sector out;const Q R=Q(.75L),h=Q(.5L)+R;S u=(S(index)+S(Q(.5L)))/S(4);auto gamma=td::curve(domain,m,r,boundary,u);S tangent[2]={gamma.d[0]/S(4),gamma.d[1]/S(4)},diff[2]={gamma.x[0]-S(loop.anchor[0]),gamma.x[1]-S(loop.anchor[1])};Q second[2]={};
    if(boundary.edge>=0){Q anchor[2]={gamma.X.n,gamma.Y.n},rr[2];int a=boundary.edge,b=(a+1)%3;S tdot=(boundary.hi-boundary.lo)/S(4),D[2]={(S(Q(r.triangle.geometry.x[b][0]))-S(Q(r.triangle.geometry.x[a][0])))*tdot,(S(Q(r.triangle.geometry.x[b][1]))-S(Q(r.triangle.geometry.x[a][1])))*tdot};for(int k=0;k<2;k++)rr[k]=sum(k?gamma.Y.e:gamma.X.e,product(h,ti::mag(D[k])));auto edge_map=tg::compile(r,anchor,p.parameters[3]);auto eb=bounds(edge_map,p,rr);if(!eb.pass){out.reason=eb.reason;return out;}for(int k=0;k<2;k++)for(int i=0;i<2;i++)for(int j=0;j<2;j++)second[k]=sum(second[k],product(eb.H[k][i][j],product(ti::mag(D[i]),ti::mag(D[j]))));}
    Q large[2],small[2];for(int k=0;k<2;k++){large[k]=sum(ti::mag(diff[k]),sum(product(h,ti::mag(tangent[k])),product(product(h,h)/2,second[k])));small[k]=sum(ti::mag(diff[k]),sum(product(Q(.5L),ti::mag(tangent[k])),product(Q(.125L),second[k])));out.physical_radius[k]=std::max(large[k],product(Q(1)+R,small[k]));}
    S J0=td::cross(diff,tangent);Q Ju=sum(ti::mag(J0),product(h,sum(product(large[0],second[1]),product(large[1],second[0])))),Js=sum(ti::mag(J0),product(Q(.5L),sum(product(small[0],second[1]),product(small[1],second[0]))));out.Jfan=std::max(Ju,product(Q(1)+R,Js));
    auto initial=tg::inverse(m,r,S(loop.anchor[0]),S(loop.anchor[1]));Q anchor[2]={initial.X.n,initial.Y.n};auto local=tg::compile(r,anchor,p.parameters[3]);auto center=tg::evaluate<Q>(local,S(anchor[0]),S(anchor[1]));S det=center.F[0]*center.F[3]-center.F[1]*center.F[2];Q A[4]={(center.F[3]/det).n,(-center.F[1]/det).n,(-center.F[2]/det).n,(center.F[0]/det).n},forcing[2]={};
    for(int i=0;i<2;i++){S offset;for(int k=0;k<2;k++){offset=offset+S(A[2*i+k])*(center.position[k]-S(loop.anchor[k]));forcing[i]=sum(forcing[i],product(fabsq(A[2*i+k]),out.physical_radius[k]));}forcing[i]=sum(forcing[i],ti::mag(offset));out.ref_radius[i]=sum(product(Q(1.5L),forcing[i]),Q(1e-20L));}
    out.field=bounds(local,p,out.ref_radius,loop.anchor,out.physical_radius);if(!out.field.pass){out.reason=out.field.reason;return out;}
    for(int i=0;i<2;i++){Q row=0;for(int j=0;j<2;j++){S E(i==j?1:0);for(int k=0;k<2;k++)E=E-S(A[2*i+k])*center.F[2*k+j];Q e=ti::mag(E);for(int k=0;k<2;k++)for(int l=0;l<2;l++)e=sum(e,product(fabsq(A[2*i+k]),product(out.field.H[k][j][l],out.ref_radius[l])));row=sum(row,product(e,out.ref_radius[j]));}out.contraction=std::max(out.contraction,quotient_up(row,out.ref_radius[i]));out.invariance_ratio=std::max(out.invariance_ratio,quotient_up(sum(forcing[i],row),out.ref_radius[i]));}if(out.contraction>=1||out.invariance_ratio>=1){out.reason="complex_inverse_box_not_invariant";return out;}
    S f16(1),f32(1);for(int k=2;k<=32;k++){f32=f32*S(k);if(k<=16)f16=f16*S(k);}S ratio=f16*f16/f32,C=ratio*ratio/S(33),radius_factor=mf::power(S(R),Q(-32));Q coefficient=product(Q(2),ti::mag(C*radius_factor));for(int k=0;k<12;k++)out.remainder[k]=product(coefficient,product(out.Jfan,out.field.moment[k]));out.pass=true;out.reason="pass";return out;
}
}
#endif
